-- GENERATED by tools/gen_state_mod.py from templates/state_names and data/states/us_new_mexico; edit those, not this file.
-- Game script flow (content/square_names_us_new_mexico/rename.script.lua) against a fake world: queue in the build event,
-- rename only from update (no callback), map editor no-op, unknown town no-op, player renames and joined
-- groups skipped, stations by kind, params, owner rule. Fake cities via stub_module.
-- Second half: Phase 2 edge cases (plans/square_state_names/PLAN.md), each against the same fake world.

local MOD = "square_names_us_new_mexico"
local P = MOD .. "::/" .. MOD .. "/"

local CITIES = {
	["Seattle"] = {
		streets = { "Pike Street", "Pine Street" },
		neighborhoods = { "Ballard" },
		rail = { "King Street" },
		airport = { "Sea-Tac Airport" },
		harbor = { "Colman Dock" },
	},
}

local CT = {}
for _, k in ipairs({ "NAME", "TOWN", "STATION_GROUP", "STATION", "CONSTRUCTION" }) do CT[k] = k end

local function world(opts)
	opts = opts or {}
	local w = { comps = {}, sent = {}, pending = {}, town = {}, params = opts.params or {}, now = 1000,
		contested = opts.contested or {} }
	function w.add(e, k, v)
		w.comps[e] = w.comps[e] or {}
		w.comps[e][k] = v
	end
	function w.name(e) return w.comps[e] and w.comps[e].NAME and w.comps[e].NAME.name or nil end
	w.add(1, "TOWN", {}); w.add(1, "NAME", { name = opts.townName or "Seattle" })
	w.add(2, "TOWN", {}); w.add(2, "NAME", { name = "Smallville" })
	-- existing stop in Seattle: group 10 "Pike Street", station 11
	w.add(10, "STATION_GROUP", { stations = { 11 } }); w.add(10, "NAME", { name = "Pike Street" })
	w.add(11, "STATION", { terminals = { { passengersLoad = true } } }); w.town[11] = 1
	--- a new station `st` in group `g`, town `town`, default name `name`
	function w.station(g, st, town, name, terminals)
		w.add(g, "STATION_GROUP", { stations = { st } }); w.add(g, "NAME", { name = name })
		w.add(st, "STATION", { terminals = terminals or { { passengersLoad = true, passengersUnload = true } } })
		w.town[st] = town
	end
	--- the engine applies deferred renames (w.deferNames)
	function w.applyNames()
		for _, cmd in ipairs(w.pending) do w.add(cmd.e, "NAME", { name = cmd.n }) end
		w.pending = {}
	end
	--- bulldoze: the entity and its town link are gone, and it leaves its group (empty groups go too)
	function w.remove(e)
		w.comps[e] = nil
		w.town[e] = nil
		for g, c in pairs(w.comps) do
			if c.STATION_GROUP then
				for i = #c.STATION_GROUP.stations, 1, -1 do
					if c.STATION_GROUP.stations[i] == e then table.remove(c.STATION_GROUP.stations, i) end
				end
				if #c.STATION_GROUP.stations == 0 then w.comps[g] = nil end
			end
		end
	end
	w.api = {
		type = { ComponentType = CT },
		engine = {
			getComponent = function(e, k) return w.comps[e] and w.comps[e][k] or nil end,
			entityExists = function(e) return w.comps[e] ~= nil end,
			getEntitiesWithComponent = function(k)
				local out = {}
				for e, c in pairs(w.comps) do if c[k] then out[#out + 1] = e end end
				table.sort(out)
				return out
			end,
			config = {
				getModParams = function()
					local m = { [MOD] = w.params, [""] = { isMapEditor = opts.mapEditor == true } }
					for _, id in ipairs(opts.otherMods or {}) do m[id] = {} end
					return m
				end,
				getConfigDict = function() return { climate = "::/climates/temperate/temperate.clima",
					nameList = opts.nameList or (MOD .. "::/names/" .. MOD .. "/x.names") } end,
			},
			util = { getEntityName = function(e) return w.name(e) end },
			system = {
				stationSystem = {
					getTown = function(s) return w.town[s] or -1 end,
					getStations = function(t)
						local out = {}
						for s, town in pairs(w.town) do if town == t then out[#out + 1] = s end end
						table.sort(out)
						return out
					end,
					getTown2StationsMap = function()
						local m = {}
						for s, t in pairs(w.town) do
							m[t] = m[t] or {}
							table.insert(m[t], s)
						end
						return m
					end,
				},
				stationGroupSystem = { getStationGroup = function(s)
					for e, c in pairs(w.comps) do
						if c.STATION_GROUP then
							for _, x in ipairs(c.STATION_GROUP.stations) do if x == s then return e end end
						end
					end
					return -1
				end },
			},
		},
		cmd = {
			makeEntitySetNameCmd = function(e, n, f) return { e = e, n = n, f = f } end,
			sendCommand = function(cmd, cb)
				if cb then error("Callbacks are currently disallowed") end
				if w.inEvent then error("Assertion '!m_betweenChanges' failed") end
				w.sent[#w.sent + 1] = cmd
				if w.deferNames then
					w.pending[#w.pending + 1] = cmd
				else
					w.add(cmd.e, "NAME", { name = cmd.n })
				end
			end,
		},
	}
	return w
end

local function fakeState()
	local st = { v = nil, subs = false, events = {} }
	return {
		raw = st,
		get = function(_) return st.v end,
		set = function(_, v) st.v = v end,
		hasEventSubscriptions = function(_) return st.subs end,
		subscribeToNoEvents = function(_) st.subs = true end,
		subscribeToEvent = function(_, n) st.events[#st.events + 1] = n end,
	}
end

local function load(w)
	reset_modules()
	set_global("data", nil)
	set_global("api", w.api)
	set_global("print", function() end)
	set_global("require", function(p) return ug_require(p) end)
	set_global("os", setmetatable({ time = function() return w.now end }, { __index = os }))
	stub_module(P .. "data/cities.lua", CITIES)
	stub_module(P .. "data/state.lua", {})
	stub_module(P .. "data/contested.lua", w.contested)
	ug_require(P .. "rename.script.lua")
	return data()
end

--- A player build: Road Stops (edge objects) and/or constructions.
local function build(script, state, w, stops, cons, opts)
	opts = opts or {}
	local eos = {}
	for _, st in ipairs(stops or {}) do eos[#eos + 1] = { category = 0, resultEntity = st } end
	local toAdd = {}
	for _ in ipairs(cons or {}) do toAdd[#toAdd + 1] = {} end
	local proposal = { toAdd = toAdd, toRemove = opts.toRemove or {}, proposal = { edgeObjectsToAdd = eos,
		new2oldEdgeObjects = opts.n2o or {}, old2newEdgeObjects = opts.o2n or {} } }
	w.inEvent = true
	script.handleEvent({}, state, "builder", "apply_command", "onPostBuildProposal",
		{ proposal, {}, cons or {}, opts.player ~= false })
	w.inEvent = false
end

local function tick(script, state, w, seconds)
	w.now = w.now + (seconds or 2)
	script.update({}, state, 0.2)
end

before_each(function() set_global("os", os) end)

test("stop: queued in the event, renamed from update after the delay", function()
	local w = world()
	local script = load(w)
	local state = fakeState()
	script.update({}, state, 0.2)
	ok(state.raw.subs, "subscribed lazily")
	eq(state.raw.events, { "onPostBuildProposal" })
	w.station(20, 21, 1, "Main Street")
	build(script, state, w, { 21 })
	eq(#w.sent, 0, "no command in the build event")
	eq(#state.raw.v.q, 1, "queued via state")
	script.update({}, state, 0.2)
	eq(#w.sent, 0, "waits for the delay")
	tick(script, state, w)
	eq(#w.sent, 1)
	eq(w.sent[1].e, 20)
	eq(w.sent[1].n, "Pine Street", "Pike Street is already used in this town")
	eq(w.sent[1].f, nil, "plain rename of the group")
	eq(#state.raw.v.q, 0, "queue cleared")
	tick(script, state, w)
	eq(#w.sent, 1, "renamed once")
end)

