test("stations by kind get the city's names; cargo, helipads and upgrades don't", function()
	local w = world()
	local script = load(w)
	local state = fakeState()
	script.update({}, state, 0.2)
	local function con(e, file, st, g, name, terminals)
		w.station(g, st, 1, name, terminals)
		w.add(e, "CONSTRUCTION", { fileName = file, stations = { st } })
	end
	con(100, "stations/rail/modular_station/modular_station.con", 101, 102, "Seattle Station")
	con(110, "stations/air/airport.con", 111, 112, "Seattle Airport")
	con(120, "stations/water/harbor_modular.con", 121, 122, "Seattle Harbor")
	con(130, "stations/street/modular_street_station/modular_terminal.con", 131, 132, "Seattle Bus Station")
	con(140, "stations/air/heliport.con", 141, 142, "Seattle Heliport")
	con(150, "stations/rail/modular_station/modular_station.con", 151, 152, "Seattle Cargo",
		{ { cargoLoad = true, passengersLoad = false } })
	build(script, state, w, nil, { 100, 110, 120, 130, 140, 150 })
	tick(script, state, w)
	local got = {}
	for _, c in ipairs(w.sent) do got[c.e] = c.n end
	eq(got, { [102] = "King Street", [112] = "Sea-Tac Airport", [122] = "Colman Dock", [132] = "Ballard" })
	-- a second train station: list exhausted, default name stays
	con(160, "stations/rail/modular_station/modular_station.con", 161, 162, "Seattle Station #2")
	build(script, state, w, nil, { 160 })
	tick(script, state, w)
	eq(#w.sent, 4)
	-- an upgrade (the proposal removes the old construction) is never renamed
	con(170, "stations/air/airport.con", 171, 172, "Seattle Airport #2")
	CITIES["Seattle"].airport[2] = "Boeing Field"
	build(script, state, w, nil, { 170 }, { toRemove = { 110 } })
	tick(script, state, w)
	CITIES["Seattle"].airport[2] = nil
	eq(#w.sent, 4)
end)

