-- Phase 2: edge cases

--- world + loaded script + state, already subscribed
local function setup(opts)
	local w = world(opts)
	local script = load(w)
	local state = fakeState()
	script.update({}, state, 0.2)
	return w, script, state
end

local function sentTo(w)
	local got = {}
	for _, c in ipairs(w.sent) do got[c.e] = c.n end
	return got
end

--- what the game does on save/load: plain data only, a deep copy
local function saveCopy(v, path)
	path = path or "state"
	local t = type(v)
	if t == "string" or t == "boolean" then return v end
	if t == "number" then
		assert(v == v and v ~= math.huge and v ~= -math.huge, path .. ": not a finite number")
		return v
	end
	assert(t == "table", path .. ": " .. t .. " can't be saved")
	local out = {}
	for k, x in pairs(v) do
		assert(type(k) == "string" or type(k) == "number", path .. ": bad key type")
		out[k] = saveCopy(x, path .. "." .. tostring(k))
	end
	return out
end

test("two-sided stop: one station with two terminals, renamed once", function()
	local w, script, state = setup()
	w.station(20, 21, 1, "Main Street", { { passengersLoad = true }, { passengersLoad = true } })
	build(script, state, w, { 21 })
	tick(script, state, w)
	eq(sentTo(w), { [20] = "Pine Street" })
end)

