	table.insert(w.comps[20].STATION_GROUP.stations, 22)
	build(script, state, w, { 21, 22 })
	tick(script, state, w)
	eq(#w.sent, 1)
	eq(sentTo(w), { [20] = "Pine Street" })
end)

