test("stops a proposal only re-creates (road upgrade, edge split) are never queued", function()
	local w, script, state = setup()
	w.add(10, "NAME", { name = "My Favourite Stop" })
	-- the engine re-created stop 11 as 21 (same group), and 31 is a really new stop on the same street
	w.station(20, 21, 1, "My Favourite Stop"); w.station(30, 31, 1, "Main Street")
	build(script, state, w, { 21, 31 }, nil, { n2o = { [-400000000] = { 11 } } })
	eq(#state.raw.v.q, 1, "only the new stop")
	eq(state.raw.v.q[1].st, 31)
	-- the same, told by the real id or by old2newEdgeObjects
	build(script, state, w, { 21 }, nil, { n2o = { [21] = { 11 } } })
	build(script, state, w, { 21 }, nil, { o2n = { [11] = { 21 } } })
	eq(#state.raw.v.q, 1)
	tick(script, state, w)
	eq(sentTo(w), { [30] = "Pike Street" }, "the old stop was renamed by the player, so Pike Street is free")
	eq(w.name(20), "My Favourite Stop")
end)

test("player renames: a renamed stop is never touched again and its name counts as used", function()
	local w, script, state = setup()
	w.station(20, 21, 1, "Main Street")
	build(script, state, w, { 21 })
	tick(script, state, w)
	eq(w.name(20), "Pine Street")
	w.add(20, "NAME", { name = "Corner Shop" })        -- player renames our stop
	w.add(10, "NAME", { name = "Pine Street" })        -- and the old one to a city street
	w.station(30, 31, 1, "Front Street")
	build(script, state, w, { 31 })
	tick(script, state, w)
	eq(#w.sent, 2)
	eq(w.sent[2].e, 30)
	eq(w.sent[2].n, "Pike Street", "Pine Street is taken by the player's rename, Pike Street is free again")
	eq(w.name(20), "Corner Shop")
end)

