test("entity ids reused before the rename: only the new stop is named, once", function()
	local w, script, state = setup()
	w.station(20, 21, 1, "Main Street")
	build(script, state, w, { 21 })
	w.remove(21)
	w.station(50, 21, 1, "Cedar Street")                -- id 21 reused by a new stop in a new group
	build(script, state, w, { 21 })
	eq(#state.raw.v.q, 1, "the same station id is queued once")
	tick(script, state, w)
	eq(#w.sent, 0, "group changed since the first build: skipped, safe side")
	-- reused by something that isn't a station: no-op
	w.station(60, 61, 1, "Elm Street")
	build(script, state, w, { 61 })
	w.remove(61)
	w.add(61, "NAME", { name = "an edge" })
	tick(script, state, w)
	eq(#w.sent, 0)
end)

test("quick succession, renames not applied yet: no duplicate across passes", function()
	local w, script, state = setup()
	w.deferNames = true
	w.station(20, 21, 1, "Main Street")
	build(script, state, w, { 21 })
	w.now = w.now + 1
	w.station(30, 31, 1, "Front Street")
	build(script, state, w, { 31 })
	script.update({}, state, 0.2)                        -- first stop due, second still waits
	eq(#w.sent, 1)
	eq(w.sent[1].n, "Pine Street")
	eq(#state.raw.v.q, 1, "the young entry stays queued")
	tick(script, state, w, 1)                            -- engine hasn't applied "Pine Street" yet
	eq(#w.sent, 2)
	eq(w.sent[2].n, "Pike Street East")
	w.applyNames()
end)

test("many stops and stations in one build, two towns: no duplicate picks", function()
	local w, script, state = setup()
	w.add(3, "TOWN", {}); w.add(3, "NAME", { name = "Tacoma" })
	CITIES["Tacoma"] = { streets = { "Pacific Avenue", "Pike Street" }, rail = { "King Street", "Freighthouse" } }
	local stops = {}
	for i = 1, 6 do
		local town = (i % 2 == 0) and 3 or 1
		w.station(200 + 10 * i, 201 + 10 * i, town, "Default " .. i)
		stops[#stops + 1] = 201 + 10 * i
	end
	w.station(102, 101, 1, "Seattle Station")
	w.add(100, "CONSTRUCTION", { fileName = "stations/rail/modular_station/modular_station.con", stations = { 101 } })
	w.station(302, 301, 3, "Tacoma Station")
	w.add(300, "CONSTRUCTION", { fileName = "stations/rail/modular_station/modular_station.con", stations = { 301 } })
	build(script, state, w, stops, { 100, 300 })
	tick(script, state, w)
	CITIES["Tacoma"] = nil
	eq(#w.sent, 8)
	local perTown, stations = { [1] = {}, [3] = {} }, {}
	for _, c in ipairs(w.sent) do
		if c.e == 102 or c.e == 302 then
			ok(not stations[c.n], "station names unique map-wide: " .. c.n)
			stations[c.n] = true
		else
			local town = ((c.e - 200) / 10) % 2 == 0 and 3 or 1
			ok(not perTown[town][c.n], "street names unique per town: " .. c.n)
			perTown[town][c.n] = true
		end
	end
	eq(stations, { ["King Street"] = true, ["Freighthouse"] = true })
end)

test("queue cap: a huge build queues 64 stops, all handled in one pass", function()
	local w, script, state = setup()
	local stops = {}
	for i = 1, 70 do
		w.station(1000 + 2 * i, 1001 + 2 * i, 2, "Default " .. i)   -- Smallville: no renames, only the cap
		stops[#stops + 1] = 1001 + 2 * i
	end
	build(script, state, w, stops)
	eq(#state.raw.v.q, 64)
	tick(script, state, w)
	eq(#state.raw.v.q, 0)
end)

test("map editor: a queue loaded from a save is neither run nor changed", function()
	local w = world({ mapEditor = true })
	local script = load(w)
	local state = fakeState()
	w.station(20, 21, 1, "Main Street")
	state.raw.v = { v = 1, b = 1, q = { { st = 21, k = "stop", g = 20, n = "Main Street", b = 1, t = 1 } } }
	tick(script, state, w)
	tick(script, state, w)
	eq(#w.sent, 0)
	eq(#state.raw.v.q, 1)
	ok(not state.raw.subs)
end)

test("default-name collisions: engine names in use count without suffixes; a fitting default is kept", function()
	local w, script, state = setup()
	w.add(10, "NAME", { name = "Pine Street East" })    -- the existing stop's engine name (pool + suffix)
	w.station(20, 21, 1, "Pike Street")                 -- new stop: the engine already picked our first choice
	w.station(30, 31, 1, "Main Street")
	build(script, state, w, { 21, 31 })
	tick(script, state, w)
	eq(sentTo(w), { [30] = "Pike Street East" }, "no command for 20, and its name isn't handed out again")
	-- a station: "King Street Station" in another town blocks "King Street" (map-wide, without Station)
	w.station(90, 91, 2, "King Street Station")
	w.station(102, 101, 1, "Seattle Station")
	w.add(100, "CONSTRUCTION", { fileName = "stations/rail/modular_station/modular_station.con", stations = { 101 } })
	build(script, state, w, nil, { 100 })
	tick(script, state, w)
	eq(#w.sent, 1, "list exhausted: default kept")
end)

test("several state mods: own set or regional set active; another mod's rename wins", function()
	local w, script, state = setup({ nameList = MOD .. "::/names/" .. MOD .. "/x_westside.names" })
	w.station(20, 21, 1, "Main Street")
	build(script, state, w, { 21 })
	tick(script, state, w)
	eq(#w.sent, 1)
	-- base set: both mods know the town; the other one renamed it first -> ours leaves it
	local w2, script2, state2 = setup({ nameList = "::/names/usa/usa.names" })
	w2.station(20, 21, 1, "Main Street")
	build(script2, state2, w2, { 21 })
	w2.add(20, "NAME", { name = "Burnside Street" })
	tick(script2, state2, w2)
	eq(#w2.sent, 0)
end)

test("save/load with a non-empty queue: plain data, finished once after load", function()
	local w, script, state = setup()
	w.station(20, 21, 1, "Main Street")
	w.station(30, 31, 1, "Front Street")
	build(script, state, w, { 21, 31 })
	local saved = saveCopy(state.raw.v)
	-- load in a new session: fresh Lua state, the clock earlier than the saved build time
	local script2 = load(w)
	local state2 = fakeState()
	state2.raw.v = saveCopy(saved)
	w.now = 10
	script2.update({}, state2, 0.2)
	eq(#w.sent, 2)
	eq(w.sent[1].n, "Pine Street")
	eq(w.sent[2].n, "Pike Street East")
	eq(#state2.raw.v.q, 0)
	saveCopy(state2.raw.v)
	script2.update({}, state2, 0.2)
	eq(#w.sent, 2)
end)

test("save/load with an old or broken state: reset, nothing renamed, no error", function()
	local w = world()
	local script = load(w)
	for _, bad in ipairs({
		{ v = 99, q = { { st = 21 } } },
		{ v = 1, q = "x" },
		{ v = 1, q = { "x", { st = "y" }, { k = "stop" } } },
		"garbage",
	}) do
		local state = fakeState()
		state.raw.v = bad
		w.station(20, 21, 1, "Main Street")
		tick(script, state, w)
		build(script, state, w, nil, nil)
		tick(script, state, w)
		eq(#w.sent, 0)
	end
end)

test("state stays small and plain: only the queue, with numbers and strings", function()
	local w, script, state = setup()
	w.station(20, 21, 1, "Main Street")
	w.api.engine.util.getEntityName = function(e) return w.name(e) end
	build(script, state, w, { 21 })
	saveCopy(state.raw.v)
	local keys = {}
	for k in pairs(state.raw.v) do keys[#keys + 1] = k end
	table.sort(keys)
	eq(keys, { "b", "q", "v" })
end)

