-- Shared city names between series mods (G9, data/contested.lua)

local OTHER = "square_names_us_zzbigger"

local function contestedRun(opts)
	local w = world(opts)
	local script = load(w)
	local state = fakeState()
	script.update({}, state, 0.2)
	w.station(20, 21, 1, "Main Street")
	build(script, state, w, { 21 })
	tick(script, state, w)
	return w
end

test("contested city: the bigger city's mod is active and a base set is in use -> skipped", function()
	local w = contestedRun({ nameList = "::/names/usa/usa.names", contested = { seattle = OTHER }, otherMods = { OTHER } })
	eq(#w.sent, 0)
end)

test("contested city: winner not active -> renamed as usual", function()
	local w = contestedRun({ nameList = "::/names/usa/usa.names", contested = { seattle = OTHER } })
	eq(#w.sent, 1)
	eq(w.sent[1].n, "Pine Street")
end)

test("contested city: our own name set in use -> renamed even with the winner active", function()
	local w = contestedRun({ contested = { seattle = OTHER }, otherMods = { OTHER } })
	eq(#w.sent, 1)
end)

test("contested city: this mod is the winner -> renamed", function()
	local w = contestedRun({ nameList = "::/names/usa/usa.names", contested = { seattle = MOD }, otherMods = { OTHER } })
	eq(#w.sent, 1)
end)

test("contested data missing or broken: renamed as usual", function()
	local w = contestedRun({ nameList = "::/names/usa/usa.names", contested = { seattle = 42 }, otherMods = { OTHER } })
	eq(#w.sent, 1)
end)

