-- Performance guards (2026-10-08 review): cheap paths for builds without stations and for idle frames.

--- Wraps w.api.engine.<path> so calls are counted in w.calls[key].
local function countCalls(w, key, tbl, fname)
	w.calls = w.calls or {}
	w.calls[key] = 0
	local orig = tbl[fname]
	tbl[fname] = function(...)
		w.calls[key] = w.calls[key] + 1
		return orig(...)
	end
end

test("perf: a build without constructions never scans its result entities", function()
	local w, script, state = setup()
	local orig = w.api.engine.getComponent
	local conReads = 0
	w.api.engine.getComponent = function(e, k)
		if k == "CONSTRUCTION" then conReads = conReads + 1 end
		return orig(e, k)
	end
	-- a long track or road: many new edges and nodes in the result, no constructions in toAdd
	local result = {}
	for i = 1, 200 do result[i] = 5000 + i end
	w.inEvent = true
	script.handleEvent({}, state, "builder", "apply_command", "onPostBuildProposal",
		{ { toAdd = {}, toRemove = {}, proposal = { edgeObjectsToAdd = {} } }, {}, result, true })
	w.inEvent = false
	eq(conReads, 0)
end)

test("perf: unreadable toAdd -> the result entities are still scanned", function()
	local w, script, state = setup()
	w.add(100, "CONSTRUCTION", { fileName = "stations/rail/modular_station/modular_station.con", stations = { 101 } })
	w.station(102, 101, 1, "Seattle Station")
	w.inEvent = true
	script.handleEvent({}, state, "builder", "apply_command", "onPostBuildProposal",
		{ { toRemove = {}, proposal = { edgeObjectsToAdd = {} } }, {}, { 100 }, true })
	w.inEvent = false
	eq(#state.raw.v.q, 1)
end)

test("perf: builds without stations don't read mod params", function()
	local w, script, state = setup()
	countCalls(w, "params", w.api.engine.config, "getModParams")
	for _ = 1, 5 do build(script, state, w, nil, nil) end
	eq(w.calls.params, 0)
	eq(state.raw.v, nil, "nothing queued")
end)

test("perf: idle frames read the state once per second", function()
	local w, script, state = setup()
	local reads = 0
	local get = state.get
	state.get = function(self) reads = reads + 1; return get(self) end
	w.now = w.now + 1
	for _ = 1, 60 do script.update({}, state, 1 / 60) end
	eq(reads, 1)
end)

test("perf: stop renames use the town's station list, not the whole-map lookup", function()
	local w, script, state = setup()
	countCalls(w, "map", w.api.engine.system.stationSystem, "getTown2StationsMap")
	w.station(20, 21, 1, "Main Street")
	build(script, state, w, { 21 })
	tick(script, state, w)
	eq(#w.sent, 1)
	eq(w.sent[1].n, "Pine Street", "the existing Pike Street is still seen")
	eq(w.calls.map, 0)
end)

test("perf: map editor frames read mod params once, not every frame", function()
	local w = world({ mapEditor = true })
	local script = load(w)
	local state = fakeState()
	countCalls(w, "params", w.api.engine.config, "getModParams")
	for _ = 1, 60 do tick(script, state, w, 1) end
	eq(w.calls.params, 1)
	ok(not state.raw.subs, "still no subscription in the map editor")
end)
